import torch
import torch.nn as nn
from torch.utils.cpp_extension import load_inline

src = r'''
#include <torch/extension.h>
#include <cuda.h>
#include <cuda_runtime.h>
#include <cuda_fp16.h>

template <typename scalar_t>
__global__ void gn_compute_stats_kernel(const __half* __restrict__ x,
                                        float* __restrict__ sum,
                                        float* __restrict__ sumsq,
                                        int N, int C, int S, int G) {
    int idx = blockIdx.x * blockDim.x + threadIdx.x;
    int total = N * C * S;
    if (idx >= total) return;

    int s = idx % S;
    int c = (idx / S) % C;
    int n = idx / (C * S);

    int group_size = C / G;
    int g = c / group_size;

    __half v = x[idx];
    float fv = __half2float(v);

    atomicAdd(&sum[(size_t)n * G + g], fv);
    atomicAdd(&sumsq[(size_t)n * G + g], fv * fv);
}

template <typename scalar_t>
__global__ void gn_apply_kernel(const __half* __restrict__ x,
                                __half* __restrict__ y,
                                const float* __restrict__ sum,
                                const float* __restrict__ sumsq,
                                const __half* __restrict__ weight,
                                const __half* __restrict__ bias,
                                int N, int C, int S, int G, float eps) {
    int idx = blockIdx.x * blockDim.x + threadIdx.x;
    int total = N * C * S;
    if (idx >= total) return;

    int s = idx % S;
    int c = (idx / S) % C;
    int n = idx / (C * S);

    int group_size = C / G;
    int g = c / group_size;

    float M = static_cast<float>(group_size) * static_cast<float>(S);
    float mean = sum[(size_t)n * G + g] / M;
    float var  = sumsq[(size_t)n * G + g] / M - mean * mean;
    float inv_std = rsqrtf(var + eps);

    __half v = x[idx];
    float fv = __half2float(v);
    float norm = (fv - mean) * inv_std;

    float w = __half2float(weight[c]);
    float b = __half2float(bias[c]);

    float out = norm * w + b;
    y[idx] = __float2half(out);
}

// ---------------------------------------------------------------------------
// Launcher wrappers
// ---------------------------------------------------------------------------

torch::Tensor gn_compute_stats(torch::Tensor x,
                               torch::Tensor sum,
                               torch::Tensor sumsq,
                               int G) {
    const int N = x.size(0);
    const int C = x.size(1);
    const int S = x.numel() / (N * C);   // flatten all spatial dims

    const int threads = 256;
    const int blocks = (N * C * S + threads - 1) / threads;

    gn_compute_stats_kernel<float><<<blocks, threads>>>(
        reinterpret_cast<const __half*>(x.data_ptr()),
        sum.data_ptr<float>(),
        sumsq.data_ptr<float>(),
        N, C, S, G);
    cudaGetLastError(); // propagate errors
    return sum;
}

torch::Tensor gn_apply(torch::Tensor x,
                       torch::Tensor y,
                       torch::Tensor sum,
                       torch::Tensor sumsq,
                       torch::Tensor weight,
                       torch::Tensor bias,
                       int G,
                       float eps) {
    const int N = x.size(0);
    const int C = x.size(1);
    const int S = x.numel() / (N * C);

    const int threads = 256;
    const int blocks = (N * C * S + threads - 1) / threads;

    gn_apply_kernel<float><<<blocks, threads>>>(
        reinterpret_cast<const __half*>(x.data_ptr()),
        reinterpret_cast<__half*>(y.data_ptr()),
        sum.data_ptr<float>(),
        sumsq.data_ptr<float>(),
        reinterpret_cast<const __half*>(weight.data_ptr()),
        reinterpret_cast<const __half*>(bias.data_ptr()),
        N, C, S, G, eps);
    cudaGetLastError();
    return y;
}

// ---------------------------------------------------------------------------
// Pybind
// ---------------------------------------------------------------------------

PYBIND11_MODULE(TORCH_EXTENSION_NAME, m) {
    m.def("gn_compute_stats", &gn_compute_stats, "GroupNorm stats (CUDA)");
    m.def("gn_apply", &gn_apply, "GroupNorm apply (CUDA)");
}
'''

module = load_inline(name='gn_cuda',
                     cpp_sources='',
                     cuda_sources=src,
                     functions=['gn_compute_stats', 'gn_apply'],
                     verbose=False)

class ModelNew(nn.Module):
    def __init__(self, num_features: int, num_groups: int, eps: float = 1e-5):
        super().__init__()
        self.num_features = num_features
        self.num_groups = num_groups
        self.eps = eps
        # affine parameters
        self.weight = nn.Parameter(torch.ones(num_features, dtype=torch.float16, device='cuda'))
        self.bias   = nn.Parameter(torch.zeros(num_features, dtype=torch.float16, device='cuda'))

    def forward(self, x: torch.Tensor) -> torch.Tensor:
        if not x.is_cuda:
            raise RuntimeError("ModelNew expects CUDA tensor")
        if x.dtype != torch.float16:
            raise RuntimeError("ModelNew expects fp16 tensor")
        N, C, *spatial = x.shape
        S = 1
        for d in spatial:
            S *= d
        # reshape to (N, C, S) where S is flattened spatial dimension
        x_flat = x.view(N, C, S)

        # allocate buffers for stats
        sum  = torch.zeros(N, self.num_groups, dtype=torch.float32, device=x.device)
        sumsq = torch.zeros_like(sum)

        # compute per-group mean & variance
        module.gn_compute_stats(x_flat, sum, sumsq, self.num_groups)

        # allocate output
        y_flat = torch.empty_like(x_flat)

        # apply normalization and affine
        module.gn_apply(x_flat, y_flat, sum, sumsq,
                        self.weight, self.bias,
                        self.num_groups, self.eps)

        # reshape back to original
        return y_flat.view_as(x)

# expose the model class as the entry point
__all__ = ['ModelNew']
